import os
import subprocess
import re

def solve(primary: str, comparison: str):
    def is_text_file(path):
        try:
            with open(path, 'tr', encoding='utf-8') as f:
                f.read()
            return True
        except (UnicodeDecodeError, IOError):
            return False

    def collect_primary_files(directory):
        primary_files = set()
        for root, dirs, files in os.walk(directory, followlinks=False):
            for file in files:
                file_path = os.path.join(root, file)
                if is_text_file(file_path):
                    try:
                        result = subprocess.run(['grep', '-F', '-w', 'alpha', file_path], capture_output=True, text=True)
                        if result.returncode == 0:
                            primary_files.add(os.path.basename(root))
                    except Exception as e:
                        raise RuntimeError(f'Failed to execute grep on {file_path}: {e}')
        return primary_files

    def collect_comparison_files(directory):
        comparison_files = set()
        for root, dirs, files in os.walk(directory, followlinks=False):
            for file in files:
                file_path = os.path.join(root, file)
                if is_text_file(file_path):
                    try:
                        result = subprocess.run(['grep', '-F', '-L', 'alpha', file_path], capture_output=True, text=True)
                        if result.returncode == 0:
                            comparison_files.add(os.path.basename(root))
                    except Exception as e:
                        raise RuntimeError(f'Failed to execute grep on {file_path}: {e}')
        return comparison_files

    primary_set = collect_primary_files(primary)
    comparison_set = collect_comparison_files(comparison)

    intersection = sorted(list(primary_set & comparison_set))
    return intersection
